// ContentView.swift — the VisiCalc UI host shell (VC2-swiftui), now computing
// on the shared Rust spreadsheet engine through its C ABI.
//
// The grid and formula bar are the auto-generated mosaic views
// (FormulaBarView / GridView from `bash scripts/build.sh`); they are *display*
// views (the SwiftUI emitter currently lowers their inputs to constant
// bindings and emits no tap handlers). So the values they show come from the
// engine-backed `SpreadsheetModel` (Engine.swift), and a small host control row
// supplies interactivity the generated views don't: arrow keys to move the
// selection, and an editable field to set the selected cell. Edits go through
// `model.setSelected`, which writes to the engine and recomputes — the same
// Rust engine the web demos run as WASM.

import SwiftUI

struct ContentView: View {
    @StateObject private var model = SpreadsheetModel()
    @State private var editText: String = ""

    var body: some View {
        VStack(alignment: .leading, spacing: 0) {
            Text("VISICALC · MOSAIC SWIFTUI DEMO · RUST ENGINE")
                .font(.system(size: 11))
                .tracking(1.0)
                .foregroundColor(Color(hex: 0x9D9D9D))
                .padding([.top, .leading, .trailing], 16)
                .padding(.bottom, 8)

            // FormulaBar — generated by mosaic-compile (display of the selected
            // cell's address + source).
            FormulaBarView(
                cellAddress: model.selectedAddress,
                formula: model.selectedRaw,
                readOnly: true,
                dispatch: { _ in }
            )

            // Grid — generated by mosaic-compile, rendered from the engine's
            // computed values.
            GridView(
                columnHeaders: ["", "A", "B", "C", "D", "E"],
                viewportRows: model.viewportRows,
                columnWidths: [48, 96, 96, 96, 96, 96],
                totalHeight: 0,
                selectedRow: model.selectedRow,
                selectedCol: model.selectedCol,
                editRow: -1,
                editCol: -1,
                editContent: "",
                dispatch: { _ in }
            )
            .padding([.leading, .trailing, .top], 16)

            // Host interaction layer (the generated views are display-only).
            hostControls
                .padding(16)

            Spacer()
        }
        .frame(maxWidth: 720, maxHeight: .infinity, alignment: .topLeading)
        .background(Color(hex: 0x1E1E1E))
        .preferredColorScheme(.dark)
        .onAppear { editText = model.selectedRaw }
    }

    private var hostControls: some View {
        VStack(alignment: .leading, spacing: 8) {
            HStack(spacing: 6) {
                navButton("◀") { move(0, -1) }
                navButton("▲") { move(-1, 0) }
                navButton("▼") { move(1, 0) }
                navButton("▶") { move(0, 1) }
                Text(model.selectedAddress)
                    .font(.system(size: 12, design: .monospaced))
                    .foregroundColor(Color(hex: 0x9D9D9D))
                    .frame(minWidth: 36)
                TextField("value or =formula", text: $editText)
                    .textFieldStyle(.roundedBorder)
                    .font(.system(size: 13, design: .monospaced))
                    .onSubmit { commit() }
                Button("Set") { commit() }
            }
            Text("Type a value or a formula (e.g. =SUM(A1:A4)) and press Enter — every dependent cell recomputes on the Rust engine.")
                .font(.system(size: 10))
                .foregroundColor(Color(hex: 0x6D6D6D))
        }
    }

    private func navButton(_ label: String, _ action: @escaping () -> Void) -> some View {
        Button(label, action: action)
            .font(.system(size: 12, design: .monospaced))
    }

    private func move(_ dr: Int, _ dc: Int) {
        model.select(row: Int(model.selectedRow) + dr, col: Int(model.selectedCol) + dc)
        editText = model.selectedRaw
    }

    private func commit() {
        model.setSelected(editText)
        editText = model.selectedRaw
    }
}

// Helper init for hex colours so we don't have to write
// `Color(red:, green:, blue:)` everywhere.
extension Color {
    init(hex: UInt32) {
        let r = Double((hex >> 16) & 0xFF) / 255.0
        let g = Double((hex >> 8) & 0xFF) / 255.0
        let b = Double(hex & 0xFF) / 255.0
        self.init(red: r, green: g, blue: b)
    }
}
